import { booleanAttribute, ChangeDetectionStrategy, Component, input } from "@angular/core";

export type PillVariant = "info" | "success" | "warning";

@Component({
    selector: "app-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill" [class]="variant()">{{ label() }}@if (!hideHint()) {<span class="hint">i</span>}</span>`
})
export class PillComponent {
    readonly hideHint = input(false, { transform: booleanAttribute });
    readonly label = input("");
    readonly variant = input<"info" | "success" | "warning">("info");
}

